import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFrame Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFrame/aireframe-v3-3-2.md","filePath":"aireblock-releases/AireFrame/aireframe-v3-3-2.md","lastUpdated":1791984229000}`),a={name:`aireblock-releases/AireFrame/aireframe-v3-3-2.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireframe-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireframe-icon.png"> AireFrame Release Notes</span> <a class="header-anchor" href="#aireframe-release-notes" aria-label="Permalink to “AireFrame Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 3.3.2<br><strong>Release Date:</strong> 14 October 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Clearer Validation for Liquid Formatters Using Sibling Values (FRAME-2714)</li><li>Table Visualisations No Longer Error When Filtering on Later Pages (FRAME-2732)</li><li>Correct Sort Order When Paging Back Through Subject Lists (FRAME-2752)</li><li>Consistent Data Types from Liquid Mappers (FRAME-2753)</li><li>Ascending and Descending Sort Now Work Alongside a Default Sort (FRAME-2754)</li><li>Offline Working Banner Stays Visible When Scrolling (FRAME-2757)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="clearer-validation-for-liquid-formatters-using-sibling-values-frame-2714" tabindex="-1">Clearer Validation for Liquid Formatters Using Sibling Values (FRAME-2714) <a class="header-anchor" href="#clearer-validation-for-liquid-formatters-using-sibling-values-frame-2714" aria-label="Permalink to “Clearer Validation for Liquid Formatters Using Sibling Values (FRAME-2714)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Liquid formatters in the Visualisation Designer that divide by a <code>sibling.*</code> value no longer fail validation with an &quot;Unexpected Execution Error&quot;. Validation now handles these expressions correctly and returns a readable message where an expression is genuinely invalid. Runtime rendering was not affected.</p></div><h4 id="table-visualisations-no-longer-error-when-filtering-on-later-pages-frame-2732" tabindex="-1">Table Visualisations No Longer Error When Filtering on Later Pages (FRAME-2732) <a class="header-anchor" href="#table-visualisations-no-longer-error-when-filtering-on-later-pages-frame-2732" aria-label="Permalink to “Table Visualisations No Longer Error When Filtering on Later Pages (FRAME-2732)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Applying a filter to a table visualisation after moving to page 2 or later no longer causes the visualisation to show an error. Changing a filter now returns you to the first page of results, and requests that go beyond the end of the data return an empty page rather than failing.</p></div><h4 id="correct-sort-order-when-paging-back-through-subject-lists-frame-2752" tabindex="-1">Correct Sort Order When Paging Back Through Subject Lists (FRAME-2752) <a class="header-anchor" href="#correct-sort-order-when-paging-back-through-subject-lists-frame-2752" aria-label="Permalink to “Correct Sort Order When Paging Back Through Subject Lists (FRAME-2752)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Moving back to a previous page of a subject list now returns rows in the requested sort order. Previously, backward paging returned the correct rows in reverse order with mislabelled page positions, so Next and Previous did not round-trip correctly.</p></div><h4 id="consistent-data-types-from-liquid-mappers-frame-2753" tabindex="-1">Consistent Data Types from Liquid Mappers (FRAME-2753) <a class="header-anchor" href="#consistent-data-types-from-liquid-mappers-frame-2753" aria-label="Permalink to “Consistent Data Types from Liquid Mappers (FRAME-2753)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Data pipeline liquid mappers now store every row using the output type the pipeline validated. Previously, a blank input in a mapper validated as a Date could be stored as text, mixing types in the series and causing subject lists sorted on that series to appear out of order. A cache rebuild is required for existing affected series to pick up the corrected type.</p></div><h4 id="ascending-and-descending-sort-now-work-alongside-a-default-sort-frame-2754" tabindex="-1">Ascending and Descending Sort Now Work Alongside a Default Sort (FRAME-2754) <a class="header-anchor" href="#ascending-and-descending-sort-now-work-alongside-a-default-sort-frame-2754" aria-label="Permalink to “Ascending and Descending Sort Now Work Alongside a Default Sort (FRAME-2754)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>On subject lists with a default ordering configured, choosing Ascending or Descending from the &quot;Order by&quot; menu now changes the list order and the choice persists. Selecting &quot;Default Sort&quot; restores the configured default. Subject lists without a default ordering are unaffected.</p></div><h4 id="offline-working-banner-stays-visible-when-scrolling-frame-2757" tabindex="-1">Offline Working Banner Stays Visible When Scrolling (FRAME-2757) <a class="header-anchor" href="#offline-working-banner-stays-visible-when-scrolling-frame-2757" aria-label="Permalink to “Offline Working Banner Stays Visible When Scrolling (FRAME-2757)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The warning banner shown when completing a form in offline mode now stays fixed at the top of the page and in front of all other content while scrolling. Previously it became partly transparent and slipped behind form sections.</p></div>`,20)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};